-- Idempotent RLS and grants. Run after schema; safe to run repeatedly.
alter table public.users enable row level security; alter table public.challenges enable row level security; alter table public.tasks enable row level security; alter table public.user_tasks enable row level security; alter table public.quiz_questions enable row level security; alter table public.articles enable row level security; alter table public.article_reads enable row level security; alter table public.campaigns enable row level security; alter table public.pledges enable row level security; alter table public.commitments enable row level security; alter table public.impact_factors enable row level security; alter table public.game_daily_scores enable row level security; alter table public.game_quiz_answers enable row level security; alter table public.waste_items enable row level security; alter table public.game_scenarios enable row level security; alter table public.game_scenario_steps enable row level security; alter table public.user_challenges enable row level security; alter table public.data_deletion_requests enable row level security;
do $$ declare r record; begin for r in select schemaname,tablename,policyname from pg_policies where schemaname='public' and tablename in ('users','challenges','tasks','user_tasks','quiz_questions','articles','article_reads','campaigns','pledges','commitments','impact_factors','game_daily_scores','game_quiz_answers','waste_items','game_scenarios','game_scenario_steps','user_challenges','data_deletion_requests') loop execute format('drop policy if exists %I on %I.%I',r.policyname,r.schemaname,r.tablename); end loop; end $$;
create policy challenges_read on public.challenges for select to anon,authenticated using(active); create policy tasks_read on public.tasks for select to anon,authenticated using(active and exists(select 1 from public.challenges c where c.id=challenge_id and c.active)); create policy articles_read on public.articles for select to anon,authenticated using(published); create policy campaigns_read on public.campaigns for select to anon,authenticated using(active); create policy factors_read on public.impact_factors for select to anon,authenticated using(active); create policy quiz_read on public.quiz_questions for select to anon,authenticated using(active); create policy waste_read on public.waste_items for select to anon,authenticated using(active); create policy scenarios_read on public.game_scenarios for select to anon,authenticated using(active); create policy scenario_steps_read on public.game_scenario_steps for select to anon,authenticated using(exists(select 1 from public.game_scenarios s where s.id=scenario_id and s.active));
create policy users_self_read on public.users for select to authenticated using(id=(select auth.uid())); create policy users_self_update on public.users for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid())); create policy commitments_insert on public.commitments for insert to authenticated with check(user_id=(select auth.uid())); create policy user_challenges_self on public.user_challenges for select to authenticated using(user_id=(select auth.uid())); create policy user_tasks_self on public.user_tasks for select to authenticated using(user_id=(select auth.uid())); create policy article_reads_self on public.article_reads for select to authenticated using(user_id=(select auth.uid())); create policy deletion_self on public.data_deletion_requests for select to authenticated using(user_id=(select auth.uid())); create policy deletion_insert on public.data_deletion_requests for insert to authenticated with check(user_id=(select auth.uid()));
create policy admin_challenges on public.challenges for all to authenticated using((auth.jwt()->'app_metadata'->>'role') in ('admin','editor')) with check((auth.jwt()->'app_metadata'->>'role') in ('admin','editor')); create policy admin_tasks on public.tasks for all to authenticated using((auth.jwt()->'app_metadata'->>'role') in ('admin','editor')) with check((auth.jwt()->'app_metadata'->>'role') in ('admin','editor')); create policy admin_quiz on public.quiz_questions for all to authenticated using((auth.jwt()->'app_metadata'->>'role') in ('admin','editor')) with check((auth.jwt()->'app_metadata'->>'role') in ('admin','editor')); create policy admin_deletion on public.data_deletion_requests for all to authenticated using((auth.jwt()->'app_metadata'->>'role')='admin') with check((auth.jwt()->'app_metadata'->>'role')='admin');
revoke select on public.quiz_questions from anon,authenticated; grant select(id,question,options,explanation,active,created_at,game_type,source) on public.quiz_questions to anon,authenticated; revoke select on public.users from anon,authenticated; grant select(id,display_name,school,faculty,class_name,avatar_url,total_points,streak_days,hide_from_leaderboard,role,created_at,updated_at,tree_level,tree_last_active,locked) on public.users to authenticated; revoke insert,delete,update on public.users from authenticated; grant update(display_name,school,faculty,class_name,avatar_url,hide_from_leaderboard) on public.users to authenticated;
revoke insert,update,delete on public.user_tasks,public.article_reads,public.game_quiz_answers,public.game_daily_scores,public.user_challenges from authenticated;
